import{c as e,Q as a,j as d,m as r}from"./chunks/framework.BXc4yaFE.js";const u=JSON.parse('{"title":"deep-practices-v2 執行計劃書 — 六主題盤點 + 排程","description":"","frontmatter":{"title":"deep-practices-v2 執行計劃書 — 六主題盤點 + 排程","date":"2026-06-07T00:00:00.000Z","branch":"feature/deep-practices-v2-plan","companion_report":"research/reports/2026-06-07-claude-code-community-practices-report.md","source_report":"research/reports/2026-06-07-claude-code-deep-practices-v2.md","type":"execution-plan"},"headers":[],"relativePath":"research/reports/archive/2026-06-07-deep-practices-v2-execution-plan.md","filePath":"research/reports/archive/2026-06-07-deep-practices-v2-execution-plan.md","lastUpdated":1785909234000}'),s={name:"research/reports/archive/2026-06-07-deep-practices-v2-execution-plan.md"};function o(n,t,i,l,c,h){return a(),d("div",null,[...t[0]||(t[0]=[r(`<h1 id="deep-practices-v2-執行計劃書" tabindex="-1">deep-practices-v2 執行計劃書 <a class="header-anchor" href="#deep-practices-v2-執行計劃書" aria-label="Permalink to &quot;deep-practices-v2 執行計劃書&quot;">​</a></h1><blockquote><p>針對使用者圈選的六個主題（iSkill 設計、§8.1 LobeHub L1-L4、§6.2 五層成本優化、§9 P0/P1/P2），盤點 workspace 現況後排程。 <strong>核心結論（前置）</strong>：六主題對應的 13 項報告行動中，<strong>多數已滿足或屬幻覺建議</strong>——真正新增且無設計衝突的小項僅 2 個。本計劃以「誠實 gap」為主軸，不把 13 項當待辦逐條鋪（符合 workspace 反湊數紀律）。</p></blockquote><hr><h2 id="第一節-盤點結論總覽" tabindex="-1">第一節：盤點結論總覽 <a class="header-anchor" href="#第一節-盤點結論總覽" aria-label="Permalink to &quot;第一節：盤點結論總覽&quot;">​</a></h2><h3 id="_1-1-三類判定-套用對稱懷疑" tabindex="-1">1.1 三類判定（套用對稱懷疑） <a class="header-anchor" href="#_1-1-三類判定-套用對稱懷疑" aria-label="Permalink to &quot;1.1 三類判定（套用對稱懷疑）&quot;">​</a></h3><p>對報告建議套用 workspace 既有紀律：不只剔除<strong>幻覺 key</strong>（技術上不存在），也剔除<strong>撞既有設計的有效建議</strong>（技術上有效，但與 workspace 刻意設計衝突 → 屬 tradeoff 非 fix，需 AskUserQuestion 不自動執行）。</p><table tabindex="0"><thead><tr><th>判定類別</th><th>數量</th><th>處置</th></tr></thead><tbody><tr><td>✅ 已滿足</td><td>5</td><td>不動，僅記錄佐證</td></tr><tr><td>🟡 部分（有真實小 gap）</td><td>4</td><td>評估後執行</td></tr><tr><td>🔴 未做（真 gap）</td><td>2</td><td>quick-win 可即執行</td></tr><tr><td>⚫ 報告建議無效（幻覺 key）</td><td>1</td><td>剔除</td></tr><tr><td>⚠️ tradeoff（撞既有設計，非 fix）</td><td>1</td><td>AskUserQuestion 待決</td></tr></tbody></table><h3 id="_1-2-主對話親驗修正子代理-verdict-unverified-success-閘門" tabindex="-1">1.2 主對話親驗修正子代理 verdict（unverified_success 閘門） <a class="header-anchor" href="#_1-2-主對話親驗修正子代理-verdict-unverified-success-閘門" aria-label="Permalink to &quot;1.2 主對話親驗修正子代理 verdict（unverified_success 閘門）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>項目</th><th>子代理 verdict</th><th>親驗結果</th><th>修正</th></tr></thead><tbody><tr><td>P0-1 <code>memory-sync.sh:44 exit 1</code></td><td>「誤用，應改 exit 0」</td><td>remote-mismatch 中止路徑，exit 1=sync 失敗但不阻斷 session（exit 2 才 block，見 <code>branch-isolation-guard.sh:14</code> 註解）</td><td><strong>語義正確，已滿足</strong>（子代理誤判）</td></tr><tr><td>P0-4 subagent model env</td><td>「未設定，建議加」</td><td>env 確無 <code>CLAUDE_CODE_SUBAGENT_MODEL</code>（已驗 settings.json）</td><td>verdict 屬實，但釘定會破壞檔數路由 → 改列 ⚠️ tradeoff</td></tr><tr><td>skill body 字數</td><td>「25/27 超標」</td><td>抽驗 opus-pilot=2986 / diagram-gen=298 / spec-implement=331 屬實</td><td>數字屬實，但<strong>詮釋錯</strong>：pilot/hub skill 多命令本不適用 450 上限</td></tr></tbody></table><hr><h2 id="第二節-六主題逐項盤點" tabindex="-1">第二節：六主題逐項盤點 <a class="header-anchor" href="#第二節-六主題逐項盤點" aria-label="Permalink to &quot;第二節：六主題逐項盤點&quot;">​</a></h2><h3 id="主題-1-—-iskill-設計-community-報告主題-i" tabindex="-1">主題 1 — iSkill 設計（community 報告主題 I） <a class="header-anchor" href="#主題-1-—-iskill-設計-community-報告主題-i" aria-label="Permalink to &quot;主題 1 — iSkill 設計（community 報告主題 I）&quot;">​</a></h3><p><strong>基準</strong>：description 雙段（Use when + Do NOT）、body 250-450 words、banlist、name ≤64。</p><p><strong>現況</strong>（27 skills）：</p><ul><li>✅ name ≤64：27/27（最長 19 chars）</li><li>✅ description 雙段格式：27/27 字面具備</li><li>🟡 description 偏短：實測 17–71 words，無一達 150 words「pushy 門檻」</li><li>⚠️ body「超標」25/27：<strong>此為 tradeoff 非 fix</strong>——opus-pilot(2986)/sre(1513)/research-hub(1531) 是多命令 pilot/hub skill，450 words 上限只適用單一指令 skill（diagram-gen 298 ✓ / spec-implement 331 ✓ 證明單指令 skill 本就達標）。盲目壓縮會砍真實操作內容，違反「不破壞 working」+「不為湊數反推」。</li></ul><p><strong>正確行動</strong>：不做 batch 壓縮。改用 <code>skill-evolution:audit</code> 對逐 skill 跑四缺陷自檢（bloated/copy-paste/brittle/awkward），由 audit 判定哪些是真冗餘、哪些是必要操作內容。→ 列 P1。</p><h3 id="主題-2-—-§8-1-lobehub-l1-l4-演化梯度" tabindex="-1">主題 2 — §8.1 LobeHub L1-L4 演化梯度 <a class="header-anchor" href="#主題-2-—-§8-1-lobehub-l1-l4-演化梯度" aria-label="Permalink to &quot;主題 2 — §8.1 LobeHub L1-L4 演化梯度&quot;">​</a></h3><p><strong>基準</strong>：L1 手動 / L2 agent 輔助人工確認 / L3 agent 主導人類關鍵判斷 / L4 agent 自主優化。</p><p><strong>workspace 定位 ≈ L2–L3（非從零起步）</strong>：</p><ul><li><code>autoload-evolution</code> skill：閉環掃描→提案→eval gate→human-gated 整合→記錄；≤1 rule/cycle + ≤50 行 diff + eval 回歸 ≥5pp 自動 revert。→ 具備 L3 的「agent 主導 + 人類保留關鍵判斷」+ 退化可觀測。</li><li><code>skill-evolution</code> skill：scan/apply/audit 對照最佳實踐自我改進。</li><li><strong>缺 L4 要件</strong>：tracing-first（per-step Execution Snapshot）+ error pattern 自動 bucket 化。</li></ul><p><strong>行動</strong>：明確認定 workspace 已在 L2–L3，不需「從 L1 起步」。L4 的 tracing instrumentation 屬重型投資，列 P2 觀察項（非承諾執行）。</p><h3 id="主題-3-—-§6-2-五層成本優化" tabindex="-1">主題 3 — §6.2 五層成本優化 <a class="header-anchor" href="#主題-3-—-§6-2-五層成本優化" aria-label="Permalink to &quot;主題 3 — §6.2 五層成本優化&quot;">​</a></h3><table tabindex="0"><thead><tr><th>層</th><th>狀態</th><th>證據</th></tr></thead><tbody><tr><td>1 Token Budgets + autoCompactAt</td><td>⚫ 無效</td><td><code>autoCompactAt</code>/<code>tokenBudget</code> 幻覺 key（Lesson 2026-06-07-C）；settings.json 已驗無此 key</td></tr><tr><td>2 Prompt Caching</td><td>✅ 完整</td><td>context-management.md：Static-first + cache_hit_rate&gt;0.7 + byte cap tokenizer 免疫</td></tr><tr><td>3 Scope-limited Sessions</td><td>✅ 完整</td><td>context-management.md：per-task 4K / per-session 30K budget + PreCompact hook</td></tr><tr><td>4 Model Routing</td><td>✅ 完整</td><td>haiku/sonnet/opus-pilot 三 skill + subagent-strategy 檔數路由表</td></tr><tr><td>5 Scoped Context References</td><td>✅ 完整</td><td>下沉原則 + path-scoped on-demand + NLAH</td></tr></tbody></table><p><strong>真實 gap</strong>：0（層 1 無效、層 2–5 已完整）。<code>CLAUDE_AUTOCOMPACT_PCT_OVERRIDE</code> env 雖為真實機制但 MEMORY 標「has bug」→ 不建議設定。</p><h3 id="主題-4–6-—-§9-p0-p1-p2-行動-13-項" tabindex="-1">主題 4–6 — §9 P0/P1/P2 行動（13 項） <a class="header-anchor" href="#主題-4–6-—-§9-p0-p1-p2-行動-13-項" aria-label="Permalink to &quot;主題 4–6 — §9 P0/P1/P2 行動（13 項）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>項</th><th>狀態</th><th>證據 / 行動</th></tr></thead><tbody><tr><td>P0-1 Hook exit code 稽核</td><td>✅ 已滿足</td><td>親驗：exit 2 阻斷用對（block-dangerous/pre-compact/pre-commit-review）；memory-sync exit 1 語義正確</td></tr><tr><td>P0-2 autoCompactAt+thinkingTokenLimit</td><td>⚫ 無效</td><td>幻覺 key</td></tr><tr><td>P0-3 釘定 Claude Code 版本</td><td>🔴 未做</td><td>當前 2.1.168，無 onboarding 最低版本標注 → <strong>quick-win</strong></td></tr><tr><td>P0-4 Subagent 模型驗證</td><td>⚠️ tradeoff</td><td>env 確無 <code>CLAUDE_CODE_SUBAGENT_MODEL</code>；但釘定破壞「0–1檔 Haiku / 2–9 Sonnet」檔數路由 → AskUserQuestion</td></tr><tr><td>P1-1 Hook Narrowness 重構</td><td>🟡 部分</td><td>block-dangerous 有 13-case fixture pair；其他 hook 缺 fixture。jq 替換屬工具偏好非強制</td></tr><tr><td>P1-2 Skill 激活率提升</td><td>✅ 已滿足</td><td><code>user-prompt-submit.sh</code> 已注入 skill routing（Twitter/YT/GH/實作關鍵字）</td></tr><tr><td>P1-3 Effort Routing</td><td>✅ 已滿足</td><td>CLAUDE.md:32 effort 矩陣完整，/effort high 為 daily 預設</td></tr><tr><td>P1-4 CLAUDE.md 精確度</td><td>✅ 已滿足</td><td>32 行 ≪ 200 上限</td></tr><tr><td>P1-5 STATUS.md handoff</td><td>✅ 已滿足</td><td><code>schemas/progress.schema.json</code> + core.md 長期記憶回路要求建 claude-progress.json</td></tr><tr><td>P2-1 Multi-Agent TDD 試點</td><td>🔴 未做</td><td>無 tdd 三件組 agent；現有 test-writer/test-engineer 部分覆蓋 → 季度級</td></tr><tr><td>P2-2 Agent Teams 評估</td><td>🔴 未做</td><td>無 <code>CLAUDE_CODE_EXPERIMENTAL_AGENT_TEAMS</code> flag → <strong>低成本試跑可即評估</strong></td></tr><tr><td>P2-3 Self-Evolving 試點</td><td>🟡 部分</td><td>autoload/skill-evolution 已達 L2–L3（見主題 2）；缺 tracing bucket</td></tr><tr><td>P2-4 Spec-Driven 三文件</td><td>🟡 部分</td><td><code>spec-implement</code> skill 已存在；無 product/tech/structure.md 範本目錄</td></tr></tbody></table><hr><h2 id="第三節-執行排程" tabindex="-1">第三節：執行排程 <a class="header-anchor" href="#第三節-執行排程" aria-label="Permalink to &quot;第三節：執行排程&quot;">​</a></h2><h3 id="即可執行-quick-win-無設計衝突" tabindex="-1">即可執行（quick-win，無設計衝突） <a class="header-anchor" href="#即可執行-quick-win-無設計衝突" aria-label="Permalink to &quot;即可執行（quick-win，無設計衝突）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>行動</th><th>規模</th><th>驗證條件</th></tr></thead><tbody><tr><td>Q1</td><td><strong>P0-3 版本釘定</strong>：README 或 onboarding 標注最低 Claude Code 版本（≥2.1.116 = 所有已知 CVE 修補；當前 2.1.168）</td><td>≤10 行</td><td>grep README 含版本要求</td></tr><tr><td>Q2</td><td><strong>P2-2 Agent Teams 試評</strong>：settings.json env 加 flag 試跑一個 3-5 子系統平行任務，記錄 wall-clock vs token，寫入報告（非永久啟用）</td><td>試跑 1 次</td><td>產出評估記錄</td></tr></tbody></table><h3 id="已決-askuserquestion-2026-06-07" tabindex="-1">已決（AskUserQuestion 2026-06-07） <a class="header-anchor" href="#已決-askuserquestion-2026-06-07" aria-label="Permalink to &quot;已決（AskUserQuestion 2026-06-07）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>決策</th><th>結果</th></tr></thead><tbody><tr><td>D1</td><td><strong>P0-4 subagent model pin</strong></td><td><strong>不釘定，維持檔數路由</strong>。靜默降級風險靠 subagent-strategy.md 文字規範 + 主對話親驗 verdict 控制（現況）。符合 workspace 成本紀律。</td></tr><tr><td>Q2</td><td><strong>Agent Teams 試評</strong></td><td><strong>本次執行</strong>（見下方執行記錄）</td></tr></tbody></table><h3 id="季度級-p1-p2-列入待辦非本次執行" tabindex="-1">季度級（P1/P2，列入待辦非本次執行） <a class="header-anchor" href="#季度級-p1-p2-列入待辦非本次執行" aria-label="Permalink to &quot;季度級（P1/P2，列入待辦非本次執行）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>行動</th><th>前置</th></tr></thead><tbody><tr><td>S1</td><td><strong>iSkill audit</strong>：跑 <code>skill-evolution:audit</code> 對 27 skill 逐個四缺陷自檢（<strong>非 batch 壓縮</strong>）</td><td>—</td></tr><tr><td>S2</td><td><strong>P1-1 hook fixture 擴充</strong>：為 block-dangerous 以外的 hook 補 fixture pair</td><td>—</td></tr><tr><td>S3</td><td><strong>P2-4 spec 三文件範本</strong>：建 docs/spec/ product/tech/structure.md 範本或在 spec-implement 加範本指引</td><td>—</td></tr><tr><td>S4</td><td><strong>P2-1 Multi-Agent TDD 試點</strong>：選中型 feature 跑 tdd 三件組，量化 regression rate</td><td>需建 3 agent</td></tr><tr><td>S5</td><td><strong>P2-3 / 主題2 L4 tracing</strong>（觀察項，非承諾）：tracing-first Execution Snapshot + error pattern bucket</td><td>重型投資，評估 ROI 後再定</td></tr></tbody></table><hr><h2 id="第三節之二-q2-agent-teams-評估記錄-2026-06-07-執行" tabindex="-1">第三節之二：Q2 Agent Teams 評估記錄（2026-06-07 執行） <a class="header-anchor" href="#第三節之二-q2-agent-teams-評估記錄-2026-06-07-執行" aria-label="Permalink to &quot;第三節之二：Q2 Agent Teams 評估記錄（2026-06-07 執行）&quot;">​</a></h2><h3 id="對稱懷疑驗證-flag-真偽" tabindex="-1">對稱懷疑驗證：flag 真偽 <a class="header-anchor" href="#對稱懷疑驗證-flag-真偽" aria-label="Permalink to &quot;對稱懷疑驗證：flag 真偽&quot;">​</a></h3><p><code>CLAUDE_CODE_EXPERIMENTAL_AGENT_TEAMS</code> <strong>是真實 flag</strong>（官方文件 <code>code.claude.com/docs/en/agent-teams</code> 確認，非幻覺 key）。需 Claude Code ≥2.1.32（當前 2.1.168 ✓）。</p><h3 id="誠實邊界-為何「本次試跑」無法在當前-session-完成" tabindex="-1">誠實邊界：為何「本次試跑」無法在當前 session 完成 <a class="header-anchor" href="#誠實邊界-為何「本次試跑」無法在當前-session-完成" aria-label="Permalink to &quot;誠實邊界：為何「本次試跑」無法在當前 session 完成&quot;">​</a></h3><p>官方文件關鍵事實：</p><ul><li>Agent Teams 是<strong>互動式 CLI session 級編排</strong>：lead session 在使用者確認後 spawn teammates，透過 tmux/in-process pane + 共享 task list（<code>~/.claude/tasks/</code>）+ mailbox 協調。</li><li><strong>「No nested teams：teammates cannot spawn their own teams or teammates. Only the lead can manage the team.」</strong></li><li>當前 runtime 是被 spawn 的 agent，<strong>無法在此 session 內程式化啟動 Agent Team</strong>。真正啟用須使用者在終端：① settings.json 加 flag → ② 重啟 CLI → ③ 自然語言要求建 team。</li></ul><p>→ 不假裝跑了（unverified_success 紀律）。評估改為「啟用指南 + workspace 適配性 + 對照決策」。</p><h3 id="subagents-現況-vs-agent-teams-決策表" tabindex="-1">Subagents（現況）vs Agent Teams 決策表 <a class="header-anchor" href="#subagents-現況-vs-agent-teams-決策表" aria-label="Permalink to &quot;Subagents（現況）vs Agent Teams 決策表&quot;">​</a></h3><table tabindex="0"><thead><tr><th>維度</th><th>Subagents（workspace 現用）</th><th>Agent Teams</th></tr></thead><tbody><tr><td>通訊</td><td>只回報 parent，child 間不通訊（subagent-strategy 鐵律）</td><td>teammates 直接互相 message + 共享 task list</td></tr><tr><td>Context</td><td>各自 context，結果摘要回 parent</td><td>各自獨立 context，不回 parent</td></tr><tr><td>token 成本</td><td>較低（摘要回主對話）</td><td>顯著較高（每 teammate 獨立 instance，線性增長）</td></tr><tr><td>協調</td><td>主 agent 手動管理（fan-out ≤4）</td><td>自協調 + 依賴自動解析</td></tr><tr><td>最適</td><td>聚焦任務、只要結果（<strong>workspace 多數研究/審查場景</strong>）</td><td>需互相挑戰/辯論的複雜任務（競爭假設除錯、跨層協調）</td></tr></tbody></table><h3 id="workspace-適配性結論" tabindex="-1">workspace 適配性結論 <a class="header-anchor" href="#workspace-適配性結論" aria-label="Permalink to &quot;workspace 適配性結論&quot;">​</a></h3><ul><li>workspace 既有 4-agent fan-out（parallel researcher）已覆蓋「平行研究/審查只要結果」場景，<strong>token 成本更低</strong>，符合成本紀律。</li><li>Agent Teams 的獨特價值在「teammates 互相辯論挑戰」（如競爭假設除錯）——這是 fan-out 做不到的（child 間不通訊）。</li><li><strong>建議</strong>：保留 subagent fan-out 為預設；Agent Teams 留給「需對抗式辯論」的特定任務，由使用者在獨立 CLI session 手動啟用。<strong>不在 settings.json 永久啟用 flag</strong>（避免每 session 多餘協調開銷 + experimental 已知限制：無 session resumption / task status lag）。</li></ul><h3 id="使用者啟用指南-下次試跑用" tabindex="-1">使用者啟用指南（下次試跑用） <a class="header-anchor" href="#使用者啟用指南-下次試跑用" aria-label="Permalink to &quot;使用者啟用指南（下次試跑用）&quot;">​</a></h3><div class="language-jsonc vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">jsonc</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// ~/.claude/settings.json（非 workspace settings，避免影響團隊）</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;env&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;CLAUDE_CODE_EXPERIMENTAL_AGENT_TEAMS&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;1&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> } }</span></span></code></pre></div><p>重啟 CLI 後，對 lead 說：「建一個 agent team，3 個 teammate 從不同角度調查 X，讓他們互相辯論挑戰對方理論」。試跑後記錄 wall-clock vs token vs 單 session 對照。</p><p><strong>已知限制（官方）</strong>：無 <code>/resume</code> 復原 in-process teammates、task status 可能 lag、shutdown 慢、一次一隊、split pane 需 tmux/iTerm2（VS Code 整合終端不支援）。</p><hr><h2 id="第四節-被剔除-不執行清單-誠實記錄" tabindex="-1">第四節：被剔除/不執行清單（誠實記錄） <a class="header-anchor" href="#第四節-被剔除-不執行清單-誠實記錄" aria-label="Permalink to &quot;第四節：被剔除/不執行清單（誠實記錄）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>報告建議</th><th>不執行原因</th></tr></thead><tbody><tr><td>P0-2 autoCompactAt + thinkingTokenLimit</td><td>幻覺 key，官方 schema 不存在（Lesson 2026-06-07-C）</td></tr><tr><td>§6.2 層1 tokenBudget settings</td><td>同上</td></tr><tr><td><code>CLAUDE_AUTOCOMPACT_PCT_OVERRIDE</code> 設定</td><td>真實 env 但 MEMORY 標「has bug」</td></tr><tr><td>skill body batch 壓縮到 450 words</td><td>pilot/hub 多命令 skill 不適用單指令上限；屬 tradeoff 非 fix</td></tr><tr><td>P0-1 memory-sync exit 1 改 exit 0</td><td>子代理誤判；exit 1 為 sync 失敗不阻斷 session 之正確語義</td></tr></tbody></table><hr><h2 id="附錄-盤點方法" tabindex="-1">附錄：盤點方法 <a class="header-anchor" href="#附錄-盤點方法" aria-label="Permalink to &quot;附錄：盤點方法&quot;">​</a></h2><ul><li>3 個並行 researcher 子代理盤點（skill 設計 / 成本 settings / P0-P1-P2 逐項）</li><li>主對話親驗關鍵 verdict（P0-1 exit code、P0-4 env、skill 字數抽驗）→ 修正 2 個子代理誤判</li><li>advisor 諮詢 → 對稱懷疑原則（剔除幻覺 key + tradeoff 建議）、LobeHub L 定位、誠實 gap 主軸</li></ul>`,56)])])}const g=e(s,[["render",o]]);export{u as __pageData,g as default};
